package com.ntd.csdl.controller;
import com.ntd.csdl.service.*;import com.ntd.csdl.config.RentalJobs;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.time.*;
@RestController @RequiredArgsConstructor @RequestMapping("/api/billing") public class BillingController{
 private final JdbcTemplate jdbc;private final LandlordService landlords;private final MonthlyBillingService billing;
 @GetMapping("/notifications") public List<Map<String,Object>> notifications(Authentication auth){return jdbc.queryForList("SELECT invoice_id AS invoiceId,message FROM invoice_notifications WHERE user_id=? AND seen=false",landlords.accountId(auth.getName()));}
 @PostMapping("/notifications/{id}/seen") public void seen(@PathVariable String id,Authentication auth){jdbc.update("UPDATE invoice_notifications SET seen=true WHERE invoice_id=? AND user_id=?",id,landlords.accountId(auth.getName()));}
 @GetMapping("/alerts") public List<Map<String,Object>> alerts(Authentication auth){return jdbc.queryForList("SELECT a.contract_id AS contractId,a.month,a.year,a.message FROM billing_alerts a JOIN contracts c ON c.contract_id=a.contract_id JOIN room_landlords l ON l.room_id=c.room_id WHERE l.user_id=? ORDER BY a.year,a.month",landlords.accountId(auth.getName()));}
 @PostMapping("/retry") public Map<String,Object> retry(Authentication auth){var now=LocalDateTime.now(ZoneId.of("Asia/Ho_Chi_Minh"));YearMonth due=RentalJobs.dueMonth(now);var starts=jdbc.queryForList("SELECT start_month FROM billing_start WHERE id=1");YearMonth first=starts.isEmpty()?YearMonth.from(now):YearMonth.from(StayService.date(starts.getFirst().get("start_month")));int ready=0;for(YearMonth m=first;!m.isAfter(due);m=m.plusMonths(1))for(String id:jdbc.query("SELECT c.contract_id FROM contracts c JOIN room_landlords l ON l.room_id=c.room_id WHERE l.user_id=?",(rs,n)->rs.getString(1),landlords.accountId(auth.getName())))if(billing.bill(id,m).equals("CREATED"))ready++;return Map.of("created",ready,"message","Đã kiểm tra các kỳ đến hạn. Hóa đơn thiếu chỉ số sẽ được thử lại sau khi bổ sung.");}
}
